import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Relationships Between Tables in AL","description":"","frontmatter":{},"headers":[],"relativePath":"tables-fields-and-business-data/relationship-between-tables.md","filePath":"tables-fields-and-business-data/relationship-between-tables.md"}`),a={name:`tables-fields-and-business-data/relationship-between-tables.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="relationships-between-tables-in-al" tabindex="-1">Relationships Between Tables in AL <a class="header-anchor" href="#relationships-between-tables-in-al" aria-label="Permalink to “Relationships Between Tables in AL”">​</a></h1><p>So far, our <code>Course</code> table has stored information about courses independently. But real business applications rarely work with isolated tables.</p><p>Imagine we&#39;re building a training management system. We have courses, students, and enrollments.</p><ul><li>A <strong>Course</strong> table stores the courses available.</li><li>A <strong>Student</strong> table stores student details.</li><li>An <strong>Enrollment</strong> table records which students have enrolled in which courses.</li></ul><p>How do we connect these tables so that an enrollment refers to a valid student and course?</p><p>In AL, one of the key tools for doing this is the <strong><code>TableRelation</code> property</strong>.</p><h2 id="what-is-tablerelation" tabindex="-1">What is <code>TableRelation</code>? <a class="header-anchor" href="#what-is-tablerelation" aria-label="Permalink to “What is TableRelation?”">​</a></h2><p><code>TableRelation</code> specifies a relationship between a field and a field in another table. It helps Business Central determine which records are valid when a user selects a related value.</p><p>For example, we could have an <code>Enrollment</code> table with a <code>&quot;Course Code&quot;</code> field that refers to the <code>&quot;Course Code&quot;</code> field in our existing <code>Course</code> table.</p><p>That way, users can select an existing course instead of manually typing an arbitrary course code.</p><h2 id="understanding-relationship-types" tabindex="-1">Understanding relationship types <a class="header-anchor" href="#understanding-relationship-types" aria-label="Permalink to “Understanding relationship types”">​</a></h2><p>In database design, we commonly describe relationships in three ways.</p><table tabindex="0"><thead><tr><th>Relationship</th><th>Example</th><th>Meaning</th></tr></thead><tbody><tr><td>One-to-one</td><td>A person and their passport record</td><td>Each person has one associated passport record, and vice versa.</td></tr><tr><td>One-to-many</td><td>One course and many enrollments</td><td>A course can have many enrollment records.</td></tr><tr><td>Many-to-many</td><td>Students and courses</td><td>A student can take many courses, and a course can have many students.</td></tr></tbody></table><p>For a many-to-many relationship, we usually introduce a linking table. In our example, <code>Enrollment</code> connects <code>Student</code> and <code>Course</code>.</p><p>These are database design concepts. In AL, the <code>TableRelation</code> property helps define field-level relationships, but it doesn&#39;t automatically design every aspect of a one-to-many or many-to-many relationship for you. <a href="https://learn.microsoft.com/de-de/dynamics365/business-central/dev-itpro/developer/devenv-set-relationships-between-tables" target="_blank" rel="noreferrer">Microsoft Learn</a></p><h2 id="practical-example-connect-enrollment-to-course" tabindex="-1">Practical example: Connect Enrollment to Course <a class="header-anchor" href="#practical-example-connect-enrollment-to-course" aria-label="Permalink to “Practical example: Connect Enrollment to Course”">​</a></h2><p>Let&#39;s build a simple relationship using the <code>Course</code> table we already created.</p><p>Our <code>Enrollment</code> table will store:</p><ul><li>An enrollment number.</li><li>The course code for the course being enrolled in.</li><li>The student&#39;s name.</li></ul><p>For now, we&#39;ll focus on connecting the enrollment to a course. We&#39;ll use a student&#39;s name directly rather than introducing a separate Student table, keeping the example manageable.</p><h3 id="step-1-create-enrollment-table-al" tabindex="-1">Step 1: Create <code>Enrollment.Table.al</code> <a class="header-anchor" href="#step-1-create-enrollment-table-al" aria-label="Permalink to “Step 1: Create Enrollment.Table.al”">​</a></h3><p>Use the next available object ID in your project. Based on our earlier examples, we&#39;ll use <code>50105</code>.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace LearningAl;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>table 50105 Enrollment</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    Caption = &#39;Enrollment&#39;;</span></span>
<span class="line"><span>    DataClassification = CustomerContent;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    fields</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        field(1; &quot;Enrollment No.&quot;; Code[20])</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Caption = &#39;Enrollment No.&#39;;</span></span>
<span class="line"><span>            DataClassification = CustomerContent;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        field(2; &quot;Course Code&quot;; Code[20])</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Caption = &#39;Course Code&#39;;</span></span>
<span class="line"><span>            DataClassification = CustomerContent;</span></span>
<span class="line"><span>            TableRelation = Course.&quot;Course Code&quot;;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        field(3; &quot;Student Name&quot;; Text[100])</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Caption = &#39;Student Name&#39;;</span></span>
<span class="line"><span>            DataClassification = CustomerContent;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    keys</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        key(PK; &quot;Enrollment No.&quot;)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Clustered = true;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="step-2-understand-the-relationship" tabindex="-1">Step 2: Understand the relationship <a class="header-anchor" href="#step-2-understand-the-relationship" aria-label="Permalink to “Step 2: Understand the relationship”">​</a></h3><p>Focus on this line:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TableRelation = Course.&quot;Course Code&quot;;</span></span></code></pre></div><p>Let&#39;s break it down:</p><ul><li><code>TableRelation</code> is the property defining the relationship.</li><li><code>Course</code> is the table we want to reference.</li><li><code>&quot;Course Code&quot;</code> is the field in that table whose values we want to use.</li></ul><p>Our Enrollment table&#39;s <code>&quot;Course Code&quot;</code> field is now related to the Course table&#39;s <code>&quot;Course Code&quot;</code> field.</p><p><strong>Why is that useful?</strong></p><p>Suppose our Course table contains these records:</p><table tabindex="0"><thead><tr><th>Course Code</th><th>Course Name</th></tr></thead><tbody><tr><td>CS101</td><td>Introduction to Programming</td></tr><tr><td>CS102</td><td>Database Fundamentals</td></tr><tr><td>CS103</td><td>Web Development</td></tr></tbody></table><p>When a user selects a course through a supported lookup, Business Central can offer these existing courses.</p><p>The relationship also helps validate entries against the referenced table. See Microsoft&#39;s <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/properties/devenv-tablerelation-property" target="_blank" rel="noreferrer">TableRelation property documentation</a>. <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/properties/devenv-tablerelation-property" target="_blank" rel="noreferrer">Microsoft Learn</a></p><h3 id="step-3-what-kind-of-relationship-have-we-created" tabindex="-1">Step 3: What kind of relationship have we created? <a class="header-anchor" href="#step-3-what-kind-of-relationship-have-we-created" aria-label="Permalink to “Step 3: What kind of relationship have we created?”">​</a></h3><p>Conceptually, this is a <strong>one-to-many relationship</strong>:</p><ul><li>One Course can be associated with many Enrollment records.</li><li>Each Enrollment record references a Course through its Course Code.</li></ul><p>For example:</p><p><strong>Course table</strong></p><table tabindex="0"><thead><tr><th>Course Code</th><th>Course Name</th></tr></thead><tbody><tr><td>CS101</td><td>Introduction to Programming</td></tr></tbody></table><p><strong>Enrollment table</strong></p><table tabindex="0"><thead><tr><th>Enrollment No.</th><th>Course Code</th><th>Student Name</th></tr></thead><tbody><tr><td>ENR001</td><td>CS101</td><td>Jane</td></tr><tr><td>ENR002</td><td>CS101</td><td>Peter</td></tr><tr><td>ENR003</td><td>CS101</td><td>Amina</td></tr></tbody></table><p>Three enrollment records refer to the same course. We haven&#39;t duplicated the course&#39;s name and description in every enrollment record.</p><p>One important detail: <code>TableRelation</code> doesn&#39;t automatically display the course name in the Enrollment table. It establishes the relationship for lookup and validation. Displaying related information is something we&#39;ll explore through pages and calculated fields later.</p><h2 id="what-about-where-filters-in-a-table-relation" tabindex="-1">What about <code>WHERE</code> filters in a table relation? <a class="header-anchor" href="#what-about-where-filters-in-a-table-relation" aria-label="Permalink to “What about WHERE filters in a table relation?”">​</a></h2><p><code>TableRelation</code> can do more than reference an entire table. It can also filter the available records.</p><p>For example, suppose our Course table eventually includes an <code>Active</code> Boolean field, and we only want users to select active courses.</p><p>We could write:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TableRelation = Course.&quot;Course Code&quot; where(Active = const(true));</span></span></code></pre></div><p>This tells Business Central to filter the related Course records so that only records with <code>Active = true</code> are eligible for the lookup.</p><p><strong>Don&#39;t add this example to your current code yet.</strong> Our Course table doesn&#39;t have an <code>Active</code> field at the moment, so we&#39;d need to add that field first.</p><p>You can also create conditional relationships based on other field values, but the simple relationship we&#39;ve implemented is enough for now. <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/properties/devenv-tablerelation-property" target="_blank" rel="noreferrer">Microsoft Learn</a></p>`,52)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};